<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import AuthModal from '../components/AuthModal.vue';
import AdCard from '../components/AdCard.vue';
import { adService } from '../services';
import { useAuthStore } from '../stores/useAuthStore';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('AdDetailView');
const route = useRoute();
const router = useRouter();
const authStore = useAuthStore();
const ad = ref(null);
const relatedAds = ref([]);
const loading = ref(true);
const error = ref('');
const authModalVisible = ref(false);
const contactVisible = ref(false);
const contactMobile = ref('');
const saved = ref(false);
const feedback = ref('');
const numberFormatter = new Intl.NumberFormat('fa-IR');
const bankLogoPath = (bank) => {
    const name = bank?.name || bank || '';
    if (name.includes('رسالت')) return '/images/banks/resalat.svg';
    if (name.includes('ملی')) return '/images/banks/melli.svg';
    if (name.includes('کشاورزی')) return '/images/banks/keshavarzi.svg';
    if (name.includes('صادرات')) return '/images/banks/saderat.svg';
    if (name.includes('مهر')) return '/images/banks/mehr-iran.svg';
    if (name.includes('مسکن')) return '/images/banks/maskan.svg';
    if (name.includes('تجارت')) return '/images/banks/tejarat.svg';
    if (name.includes('سپه')) return '/images/banks/sepah.svg';
    return '';
};
const formatNumber = (value) => numberFormatter.format(Number(value || 0));
const formatMillionMoney = (value) => `${formatNumber(value)} میلیون تومان`;
const formatCompactMoney = (value) => {
    const amount = Number(value || 0);
    return amount >= 1000000 ? `${formatNumber(Math.round(amount / 1000000))} میلیون تومان` : `${formatNumber(amount)} تومان`;
};
const typeLabel = computed(() => ad.value?.type === 'supply' ? 'واگذاری امتیاز وام' : 'تقاضای خرید امتیاز');
const bankLogo = computed(() => bankLogoPath(ad.value?.bank));

async function loadRelatedAds() {
    if (!ad.value?.bank_id) return;
    try {
        const response = await adService.getAll({ bank_id: ad.value.bank_id, per_page: 4 });
        relatedAds.value = (response.data || []).filter((item) => item.id !== ad.value.id).slice(0, 3);
    } catch (exception) { logger.warn('loadRelatedAds', 'Related advertisements could not be loaded', logException(exception)); }
}
async function loadAd() {
    loading.value = true; error.value = '';
    try {
        const response = await adService.getById(route.params.id);
        ad.value = response.data || response;
        const recent = JSON.parse(localStorage.getItem('recent_ads') || '[]');
        localStorage.setItem('recent_ads', JSON.stringify([ad.value, ...recent.filter((item) => item.id !== ad.value.id)].slice(0, 8)));
        await loadRelatedAds();
    } catch (exception) { logger.error('loadAd', 'Advertisement detail request failed', logException(exception)); error.value = exception.response?.status === 404 ? 'این آگهی پیدا نشد یا دیگر منتشر نیست.' : 'دریافت آگهی با خطا مواجه شد.'; } finally { loading.value = false; }
}
async function loadBookmarkState() { if (!authStore.isAuthenticated || !authStore.isVerified) return; try { const response = await adService.getBookmarks(); saved.value = (response?.data || []).some((item) => item.id === Number(route.params.id)); } catch (exception) { logger.warn('loadBookmarkState', 'Bookmark state could not be loaded', logException(exception)); } }
async function shareAd() { try { const data = { title: ad.value?.title, text: ad.value?.title, url: window.location.href }; if (navigator.share) await navigator.share(data); else await navigator.clipboard.writeText(window.location.href); feedback.value = 'لینک آگهی کپی شد.'; } catch (exception) { if (exception.name !== 'AbortError') logger.error('shareAd', 'Sharing failed', logException(exception)); } }
async function toggleBookmark() { authStore.syncFromStorage(); if (!authStore.isAuthenticated) { authModalVisible.value = true; return; } if (!authStore.isVerified) { window.dispatchEvent(new CustomEvent('auth:verification-required', { detail: { code: 'KYC_REQUIRED' } })); return; } try { const response = await adService.toggleBookmark(Number(ad.value.id)); saved.value = response?.bookmarked === true; feedback.value = saved.value ? 'آگهی نشان شد.' : 'آگهی از نشان‌ها حذف شد.'; } catch (exception) { feedback.value = 'تغییر وضعیت نشان انجام نشد.'; logger.error('toggleBookmark', 'Bookmark change failed', logException(exception)); } }
async function showContact() { authStore.syncFromStorage(); if (!authStore.isAuthenticated) { authModalVisible.value = true; return; } if (!authStore.isVerified) { window.dispatchEvent(new CustomEvent('auth:verification-required', { detail: { code: 'KYC_REQUIRED' } })); return; } try { const response = await adService.getContact(Number(ad.value.id)); contactMobile.value = response.mobile || response.data?.mobile || ''; contactVisible.value = true; } catch (exception) { logger.error('showContact', 'Contact request failed', logException(exception)); } }
function handleAuthenticated() { authStore.syncFromStorage(); authModalVisible.value = false; if (authStore.isVerified) showContact(); else window.dispatchEvent(new CustomEvent('auth:verification-required', { detail: { code: 'KYC_REQUIRED' } })); }
function startMessage() { if (!authStore.isAuthenticated) { authModalVisible.value = true; return; } feedback.value = 'امکان ارسال پیام پس از فعال شدن گفت‌وگو فراهم می‌شود.'; }
onMounted(async () => { authStore.syncFromStorage(); await loadAd(); await loadBookmarkState(); });
</script>

<template>
<main class="ad-detail-page" dir="rtl"><div class="ad-detail-shell max-w-7xl mx-auto px-4 sm:px-6"><button class="back-link" type="button" @click="router.push({ name: 'home' })"><i class="pi pi-arrow-right"></i>بازگشت به آگهی‌ها</button><div v-if="loading" class="detail-state" role="status"><i class="pi pi-spin pi-spinner"></i><span>در حال دریافت آگهی...</span></div><section v-else-if="error" class="detail-state detail-state--error" role="alert"><i class="pi pi-exclamation-circle"></i><h1>{{ error }}</h1><button type="button" @click="loadAd">تلاش دوباره</button></section><template v-else-if="ad">
    <nav class="breadcrumb"><button type="button" @click="router.push({ name: 'home' })">مستروام</button><i class="pi pi-angle-left"></i><span>{{ ad.province || 'استان' }}</span><i class="pi pi-angle-left"></i><span>{{ ad.city || 'شهر' }}</span><i class="pi pi-angle-left"></i><strong>{{ ad.title }}</strong></nav>
    <div class="detail-layout grid grid-cols-1 lg:grid-cols-12 gap-6 items-start max-w-7xl mx-auto px-4 sm:px-6"><article class="detail-main lg:col-span-8 space-y-6"><header class="detail-header"><div><div class="detail-kicker"><span class="type-badge" :class="ad.type">{{ typeLabel }}</span><span><i class="pi pi-clock"></i>{{ ad.time }}</span></div><h1>{{ ad.title }}</h1><p class="bank-subtitle"><i class="pi pi-building"></i>{{ ad.bank }}، {{ ad.bank_plan?.title || ad.plan || 'طرح بانکی' }}</p><div class="detail-meta"><span><i class="pi pi-map-marker"></i>{{ ad.city }}، {{ ad.province }}</span><span><i class="pi pi-eye"></i>{{ formatNumber(ad.views_count) }} بازدید</span><span><i class="pi pi-calendar"></i>{{ ad.time }}</span></div></div><div class="detail-actions"><button type="button" title="اشتراک‌گذاری" @click="shareAd"><i class="pi pi-share-alt"></i></button><button type="button" :class="{ active: saved }" :title="saved ? 'حذف از نشان‌ها' : 'نشان کردن'" @click="toggleBookmark"><i class="pi" :class="saved ? 'pi-bookmark-fill' : 'pi-bookmark'"></i></button></div></header>
        <section class="bg-white border border-gray-200/90 rounded-2xl p-5 shadow-sm space-y-4"><header class="flex items-center justify-between gap-3"><div class="flex items-center gap-2.5"><img v-if="bankLogo" class="h-9 w-9 object-contain" :src="bankLogo" :alt="`لوگوی ${ad.bank}`"><span v-else class="flex h-9 w-9 items-center justify-center rounded-lg bg-gray-50 text-gray-500"><i class="pi pi-building"></i></span><div><strong class="block text-sm font-bold text-gray-800">{{ ad.bank || 'بانک' }}</strong><span class="text-xs text-gray-500">اطلاعات تسهیلات</span></div></div><span class="rounded-lg bg-gray-100 px-2.5 py-1 text-xs text-gray-600">{{ ad.bank_plan?.title || ad.plan || 'طرح اعتبار ملی' }}</span></header><div class="bg-gray-50 rounded-xl p-3 flex justify-between items-center mb-3 font-bold"><span class="text-sm text-gray-500">مبلغ کل تسهیلات</span><strong class="text-xl text-gray-900">{{ formatCompactMoney(ad.amount) }}</strong></div><div class="text-sm"><div class="flex justify-between items-center py-2.5 border-b border-gray-100"><span class="flex items-center gap-2 text-gray-500"><i class="pi pi-percentage text-xs text-gray-400"></i>نرخ سود / کارمزد</span><strong class="text-gray-800">{{ formatNumber(ad.fee || ad.bank_plan?.interest_rate) }}٪</strong></div><div class="flex justify-between items-center py-2.5 border-b border-gray-100"><span class="flex items-center gap-2 text-gray-500"><i class="pi pi-calendar-clock text-xs text-gray-400"></i>مدت بازپرداخت و اقساط</span><strong class="text-gray-800">{{ ad.installment_count ? `${formatNumber(ad.installment_count)} ماهه` : 'ثبت نشده' }}</strong></div><div class="flex justify-between items-center py-2.5 border-b border-gray-100"><span class="flex items-center gap-2 text-gray-500"><i class="pi pi-money-bill text-xs text-gray-400"></i>قیمت واگذاری امتیاز</span><strong class="text-gray-800">{{ formatMillionMoney(ad.price) }}</strong></div><div class="flex justify-between items-center py-2.5 border-b border-gray-100"><span class="flex items-center gap-2 text-gray-500"><i class="pi pi-send text-xs text-gray-400"></i>نوع انتقال امتیاز</span><strong class="text-gray-800">{{ ad.transfer_type || ad.transfer_method || 'پیشخوان مجازی' }}</strong></div><div class="flex justify-between items-center py-2.5 last:border-none"><span class="flex items-center gap-2 text-gray-500"><i class="pi pi-shield text-xs text-gray-400"></i>وضعیت استعلام</span><span class="inline-flex items-center gap-1 rounded-lg bg-emerald-50 px-2.5 py-1 text-xs text-emerald-700"><i class="pi pi-check-circle"></i>تایید سلامت مدارک</span></div></div></section><section class="safety-box safety-box--main"><header><i class="pi pi-shield"></i><div><h2>نکات مهم برای معامله امن</h2><p>لطفاً پیش از واریز هرگونه وجه به موارد زیر توجه فرمایید:</p></div></header><ul><li><i class="pi pi-check-circle"></i><span><strong>انتقال قطعی در سامانه رسمی یا شعبه:</strong> انتقال امتیاز وام را فقط از سامانه‌های مجاز بانکی یا شعبه رسمی نهایی کنید.</span></li><li><i class="pi pi-check-circle"></i><span><strong>عدم پرداخت بیعانه:</strong> پیش از رویت مستندات و تایید صلاحیت انتقال، بیعانه یا کمیسیون پرداخت نکنید.</span></li><li><i class="pi pi-check-circle"></i><span><strong>بررسی سقف اعتبار و اعتبارسنجی:</strong> رتبه اعتبارسنجی مرآت، سمات و شرایط ضامنین بانک عامل را استعلام بگیرید.</span></li><li><i class="pi pi-check-circle"></i><span><strong>تطابق هویت صاحب حساب:</strong> نام صاحب حساب مقصد باید دقیقاً با صاحب امتیاز وام در بانک مطابقت داشته باشد.</span></li></ul><button type="button" class="report-link" @click="reportAd"><i class="pi pi-flag"></i>مشاهده مورد مشکوک؟ ثبت گزارش تخلف آگهی</button></section>
        <section class="description-section description bg-white border border-gray-150 rounded-2xl p-5"><h2>توضیحات آگهی‌دهنده</h2><p>{{ ad.description || 'توضیحی برای این آگهی ثبت نشده است.' }}</p></section>
    </article><aside class="detail-sidebar lg:col-span-4 sticky top-24 space-y-4"><section class="contact-card bg-white border border-gray-200 rounded-2xl p-5 shadow-sm"><div class="flex items-start gap-3"><span class="seller-avatar"><i class="pi pi-user"></i></span><div class="min-w-0"><span class="contact-label">آگهی‌دهنده</span><h2>{{ ad.type === 'demand' ? 'خریدار امتیاز وام' : 'فروشنده امتیاز وام' }}</h2><strong class="block truncate text-gray-800">{{ ad.advertiser_name || ad.advertiser_nickname || (ad.advertiser_mobile ? 'کاربر احراز شده' : 'آگهی‌دهنده مستروام') }}</strong><small class="mt-1 inline-flex items-center gap-1 rounded-lg bg-emerald-50 px-2 py-1 text-xs text-emerald-700"><i class="pi pi-verified"></i>احراز هویت شده</small></div></div><div class="mt-4 grid gap-2 border-t border-gray-100 pt-3 text-xs text-gray-500"><span><i class="pi pi-calendar ml-1"></i>تاریخ عضویت: {{ ad.member_since || ad.advertiser_created_at || 'عضویت فعال' }}</span><span><i class="pi pi-clock ml-1"></i>انتشار آگهی: {{ ad.time }}</span></div><button class="contact-button mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-[#A62626] py-3.5 font-bold text-white shadow-md hover:bg-[#8e2020]" type="button" @click="showContact"><i class="pi pi-phone"></i>{{ contactVisible ? contactMobile : 'دریافت اطلاعات تماس / گفتگو' }}</button><div class="secondary-actions mt-3 flex gap-2"><button type="button" @click="toggleBookmark"><i class="pi" :class="saved ? 'pi-bookmark-fill' : 'pi-bookmark'"></i>{{ saved ? 'نشان شد' : 'نشان کردن' }}</button><button type="button" @click="shareAd"><i class="pi pi-share-alt"></i>اشتراک‌گذاری</button></div><small class="privacy-note">اطلاعات تماس فقط برای کاربران تاییدشده نمایش داده می‌شود.</small></section><section class="location-card bg-white border border-gray-200 rounded-2xl p-5 shadow-sm"><h2><i class="pi pi-map-marker"></i>محدوده آگهی</h2><div class="mini-map"><span></span><span></span><i class="pi pi-map-marker"></i></div><strong>{{ ad.city }}</strong><small>{{ ad.province }}</small></section></aside></div>
    <section v-if="feedback" class="feedback" role="status">{{ feedback }}</section><section v-if="relatedAds.length" class="related-section"><div class="related-heading"><h2>آگهی‌های مشابه</h2><span>پیشنهادهای مرتبط با این بانک</span></div><div class="related-grid"><AdCard v-for="item in relatedAds" :key="item.id" :ad="item" @view="(next) => router.push({ name: 'advertisement.detail', params: { id: next.id } })" /></div></section>
    </template></div><AuthModal v-model:visible="authModalVisible" @authenticated="handleAuthenticated" /></main>
</template>

<style scoped>
.ad-detail-page{min-height:100vh;background:#f7f8fa;color:#1f2937}.ad-detail-shell{max-width:80rem;margin:0 auto;padding:28px 16px 72px}.back-link,.breadcrumb button{border:0;background:transparent;color:#a62626;cursor:pointer;font:inherit}.back-link{display:inline-flex;gap:8px;margin-bottom:24px;font-size:12px}.breadcrumb{display:flex;align-items:center;gap:8px;margin-bottom:22px;color:#89949c;font-size:11px}.breadcrumb strong{overflow:hidden;color:#374151;text-overflow:ellipsis;white-space:nowrap}.breadcrumb .pi{font-size:9px}.detail-layout{display:grid;grid-template-columns:1fr;gap:24px;align-items:start}.detail-main,.detail-sidebar{min-width:0}.detail-sidebar{position:sticky;top:24px;display:grid;gap:16px}.detail-header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:0 0 22px;border-bottom:1px solid #e5e7eb}.detail-kicker,.detail-meta{display:flex;align-items:center;flex-wrap:wrap;gap:12px;color:#7b8790;font-size:11px}.detail-kicker .pi,.detail-meta .pi{color:#a62626}.type-badge{display:inline-flex;padding:7px 12px;border-radius:999px;background:#eaf8f0;color:#287b50;font-size:11px;font-weight:700}.type-badge.demand{background:#edf4ff;color:#4265a0}.detail-header h1{margin:12px 0 8px;color:#111827;font-size:clamp(20px,3vw,29px);font-weight:900;line-height:1.55}.bank-subtitle{margin:0;color:#66747c;font-size:12px}.bank-subtitle .pi{margin-left:5px;color:#a62626}.detail-meta{margin-top:18px}.detail-actions{display:flex;gap:8px}.detail-actions button{display:grid;place-items:center;width:38px;height:38px;border:1px solid #e5e7eb;border-radius:10px;background:#fff;color:#66747c;cursor:pointer}.detail-actions button:hover,.detail-actions button.active{border-color:#e5b2ad;background:#fff5f2;color:#a62626}.safety-box{padding:20px;border:1px solid #edf0f2;border-radius:20px;background:#fff;box-shadow:0 8px 22px rgba(32,42,53,.06)}.contact-label{color:#a62626;font-size:11px;font-weight:700}.contact-card h2{margin:8px 0 16px;color:#1f2937;font-size:18px}.seller-row{display:flex;align-items:center;gap:10px;margin-bottom:16px}.seller-avatar{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:#fff1ee;color:#a62626}.seller-row strong,.seller-row small{display:block}.seller-row strong{color:#374151;font-size:12px}.seller-row small{margin-top:4px;color:#287b50;font-size:10px}.contact-button{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:14px;border:0;border-radius:12px;background:#a62626;color:#fff;cursor:pointer;font:inherit;font-size:12px;font-weight:800;box-shadow:0 10px 18px rgba(127,29,29,.15)}.contact-button:hover{background:#861f1f}.secondary-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.secondary-actions button{padding:10px;border:1px solid #e5e7eb;border-radius:10px;background:#fff;color:#66747c;cursor:pointer;font:inherit;font-size:11px}.secondary-actions button:hover{border-color:#e5b2ad;color:#a62626}.privacy-note{display:block;margin-top:14px;color:#9aa3aa;font-size:10px;line-height:1.8}.location-card h2{display:flex;align-items:center;gap:7px;margin:0 0 12px;font-size:14px}.location-card h2 .pi{color:#a62626}.mini-map{position:relative;overflow:hidden;height:130px;margin-bottom:12px;border-radius:14px;background:#e8f0ed;background-image:linear-gradient(35deg,transparent 48%,#fff 49%,#fff 51%,transparent 52%),linear-gradient(120deg,transparent 48%,#d0dfd9 49%,#d0dfd9 51%,transparent 52%);background-size:100% 100%,55px 55px}.mini-map span{position:absolute;width:130%;height:7px;border-radius:8px;background:#fff;transform:rotate(-20deg)}.mini-map span:first-child{top:30%;left:-10%}.mini-map span:nth-child(2){top:68%;left:-15%;transform:rotate(18deg)}.mini-map .pi{position:absolute;top:43%;left:48%;color:#a62626;font-size:26px}.location-card>strong,.location-card>small{display:block}.location-card>strong{color:#374151;font-size:13px}.location-card>small{margin-top:4px;color:#89949c;font-size:11px}